CREATE POLICY school_documents_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='school-documents' AND public.has_role(auth.uid(),'super_admin')); CREATE POLICY school_documents_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='school-documents' AND public.has_role(auth.uid(),'super_admin')); CREATE POLICY school_documents_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='school-documents' AND public.has_role(auth.uid(),'super_admin'));